def main():
    terms = {e[0] for e in E}
    seen = set()
    for term, cat, text, syn, see in E:
        if term in seen:
            sys.exit(f"doppelter Begriff: {term}")
        seen.add(term)
        for s in see:
            if s not in terms:
                sys.exit(f"„{term}“ verweist auf unbekannten Begriff „{s}“")
    out = {
        "titel": "ViviaMeals Küchen-Glossar",
        "eintraege": [
            {"begriff": t, "kategorie": c, "text": x, "synonyme": s, "siehe": v}
            for t, c, x, s, v in sorted(E, key=lambda e: e[0].lower())
        ],
    }
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "resources", "data", "kuechenglossar.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    cats = sorted({e[1] for e in E})
    print(f"{len(E)} Begriffe in {len(cats)} Kategorien -> {path}")

if __name__ == "__main__":
    main()
